const MW_FINANCE_HTML=`<section class="card fp-panel" id="sec-financial-reports"><div class="card-header"><span class="card-title">Financial reports</span></div><div class="fp-body"><div class="fp-fields"><label>Report view<select id="mw-finance-view" onchange="mwFinanceChange()"><option value="PERFORMANCE">Fund performance</option><option value="FUND">Fund calculation explained</option><option value="OUTGOING">Payouts, refunds &amp; expenses</option><option value="BALANCES">Member balances</option><option value="BOARD">Board report package</option></select></label><label>Fund<select id="mw-finance-fund" onchange="mwFinanceLoad()"><option value="">Choose a fund</option></select></label><label>Cash activity from<input id="mw-finance-start" type="date"></label><label>Cash activity through<input id="mw-finance-end" type="date"></label></div><div class="fp-actions"><button class="hero-btn primary" onclick="mwFinanceLoad()">Refresh report</button><button class="hero-btn secondary" onclick="mwFinanceQuarter()">This quarter</button><button class="hero-btn secondary" onclick="mwFinanceExport()">Export CSV</button><button class="hero-btn secondary" onclick="mwFinancePrint()">Print / save PDF</button><button class="hero-btn secondary" onclick="mwGoTask('QUARTERLY_REPORT')">Generate quarterly document</button></div><p id="mw-finance-status" role="status" aria-live="polite"></p><div id="mw-finance-controls"></div><div id="mw-finance-content"></div></div></section>`;
let mwFinanceData=null,mwFinanceBusy=false,mwFinanceView='',mwFinanceSearch='',mwFinanceOnly='OWING',mwFinanceSort='TOTAL',mwFinanceOutgoingType='ALL';
function mwFinancePrepare(){const select=document.getElementById('mw-finance-fund');if(!select)return;const old=select.value;select.replaceChildren(new Option('Choose a fund',''));fpFundDetails.forEach(f=>select.add(new Option(f.code+' — '+f.deceased,f.code)));select.value=old;const day=new Intl.DateTimeFormat('en-CA',{timeZone:'America/Chicago',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());if(!document.getElementById('mw-finance-start').value)document.getElementById('mw-finance-start').value=day.slice(0,4)+'-01-01';if(!document.getElementById('mw-finance-end').value)document.getElementById('mw-finance-end').value=day;}
function mwFinanceChange(){document.getElementById('mw-finance-fund').disabled=document.getElementById('mw-finance-view').value!=='FUND';mwFinanceLoad();}
function mwFinanceQuarter(){const end=new Intl.DateTimeFormat('en-CA',{timeZone:'America/Chicago',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date()),m=Number(end.slice(5,7)),start=end.slice(0,4)+'-'+String(Math.floor((m-1)/3)*3+1).padStart(2,'0')+'-01';document.getElementById('mw-finance-start').value=start;document.getElementById('mw-finance-end').value=end;mwFinanceLoad();}
async function mwFinanceLoad(){if(mwFinanceBusy)return;mwFinancePrepare();const view=document.getElementById('mw-finance-view').value,code=document.getElementById('mw-finance-fund').value,status=document.getElementById('mw-finance-status');if(view==='FUND'&&!code){status.textContent='Choose a fund to see its calculation.';return;}mwFinanceBusy=true;status.textContent='Reading report records…';try{const d=await fpCall('fp_actions_finance',{view,fundCode:code,start:document.getElementById('mw-finance-start').value,end:document.getElementById('mw-finance-end').value});mwFinanceData=d;mwFinanceView=view;status.textContent='Generated '+new Date(d.generatedAt).toLocaleString()+(d.period?' · Cash activity '+d.period.start+' through '+d.period.end:' · Current member balances')+'. Fund balances reflect current records.';mwFinanceRender();}catch(e){status.textContent=mwServiceError(e.message);document.getElementById('mw-finance-content').innerHTML='';mwFinanceData=null;}finally{mwFinanceBusy=false;}}
function mwFinanceOpenFund(code){mwSelectWorkspace('reports');mwFinancePrepare();document.getElementById('mw-finance-view').value='FUND';document.getElementById('mw-finance-fund').value=code;mwFinanceChange();}
function mwFinanceButton(label,fn,...args){return '<button class="hero-btn secondary" onclick="'+mwOn(fn,...args)+'">'+fpEscape(label)+'</button>';}
function mwFinanceRows(d){return (d.funds||[]).filter(f=>!f.error);}
function mwFinancePerformance(d){const rows=mwFinanceRows(d),fields=[['Recorded contribution cash','cash'],['Eligible family base','coreBase'],['Admin retained (5%)','adminFee'],['Calculated family share','familyShare'],['Recorded family transfers','recordedFamilyPaid'],['Verified bank adjustment','bankAdjustment'],['Remaining for review','remaining'],['Current member balances','unpaid']];let html='<h3>Fund performance · current records</h3><p>'+fpEscape(d.note||'')+'</p>'+prTable(['Fund',...fields.map(x=>x[0])],rows.map(f=>[mwFinanceButton(f.fund.code+' — '+f.fund.deceased,'mwFinanceOpenFund',f.fund.code),...fields.map(x=>mwFinanceButton(fpMoney(f[x[1]]),'mwFinanceOpenFund',f.fund.code))]).concat([['TOTAL',...fields.map(x=>fpMoney(rows.reduce((a,f)=>a+Math.round(Number(f[x[1]]||0)*100),0)/100))]]));if((d.funds||[]).some(f=>f.error))html+='<p class="fp-error">Excluded from totals: '+d.funds.filter(f=>f.error).map(f=>fpEscape(f.fund.code+': '+f.error)).join('; ')+'</p>';return html;}
function mwFinanceCalculationRows(f){return [['Confirmed contribution cash',f.cash],['Exempt-member cash identified',f.exemptCash],['Applied credit identified in trackers',f.appliedCredit],['Cash + credit − exempt cash − eligible base: difference needing review',f.unreconciledDifference],['Eligible family contribution base (existing tracker method)',f.coreBase],['Less admin retained: base × 5%',-f.adminFee],['Calculated family share',f.familyShare],['Less recorded family transfers',-f.recordedFamilyPaid],['Verified bank amount adjustment',f.bankAdjustment],['Remaining for review: share − transfers − adjustment',f.remaining],['Separately recorded late-fee receipts (outside contribution cash)',f.separateLateFees]];}
function mwFinanceFund(f,d){const s=f.states,counts=[['Cleared / credit-covered',s.cleared,'#217b31'],['Unpaid',s.unpaid,'#d68b0c'],['Partial',s.partial,'#db9d39'],['Exempt',s.exempt,'#4c9ed9'],['Review',s.review,'#8491a3']],den=Math.max(1,f.currentMembers);let at=0,segments=counts.map(x=>{const from=at;at+=x[1]/den*100;return x[2]+' '+from+'% '+at+'%';}).join(',');return '<section class="mw-report-fund"><h3>'+fpEscape(f.fund.code+' — '+f.fund.deceased)+'</h3><p>Due '+fpEscape(f.fund.deadline||'date not recorded')+' · '+fpEscape(f.fund.status)+' · '+fpMoney(f.fund.baseAmount)+' per member</p><div class="fp-fields"><div><div class="mw-report-ring" style="background:conic-gradient('+segments+')"><div><strong>'+f.currentMembers+'</strong><span>Current tracked members</span></div></div>'+counts.map(([label,count,color])=>'<p><span style="display:inline-block;width:10px;height:10px;border-radius:50%;background:'+color+'"></span> '+fpEscape(label)+' · <strong>'+count+'</strong></p>').join('')+'</div><div>'+prTable(['Family share calculation','Amount'],mwFinanceCalculationRows(f).map(([label,amount],i)=>[fpEscape(label),mwFinanceButton(fpMoney(amount),'mwFinanceProof',f.fund.code,i)]))+'</div></div><div id="mw-finance-proof-'+fpEscape(f.fund.code)+'"></div><p>'+fpEscape(f.note)+'</p><p>Embedded late fees: <strong>not independently itemized</strong>. A difference requiring review is not automatically classified as late fees or excess cash.</p><h4>How recorded contributions add up</h4>'+prTable(['Payment entries','Total'],f.distribution.map(x=>[x.count+' × '+fpMoney(x.amount),fpMoney(x.total)]).concat([['TOTAL',fpMoney(f.cash)]]))+'<details><summary>Contribution entries · '+f.receipts.length+'</summary>'+prTable(['Date','Member','Amount','Action'],f.receipts.map(r=>[fpEscape(r.date),prProfileButton(r.memberId,r.name),fpMoney(r.amount),mwFinanceButton('Inspect row '+r.row,'prInspectSource',r.row)]))+'</details><details><summary>Recorded family / other transfers</summary>'+prTable(['Date','Receiver','Category','Description','Amount'],f.payouts.map(r=>[fpEscape(r.date),fpEscape(r.receiver),fpEscape(r.type),fpEscape(r.description),fpMoney(r.amount)]))+'</details>'+prTable(['Verified adjustment','PAYOUTS row','Amount'],f.adjustments.map(a=>[fpEscape(a.explanation),String(a.payoutRow),fpMoney(a.amount)]))+'<p>Settlement and pending status are not established by the payout ledger alone.</p><details><summary>Calculation review notes · '+f.warnings.length+'</summary><ul>'+f.warnings.map(w=>'<li>'+fpEscape(w)+'</li>').join('')+'</ul></details>'+mwFinanceFundQuarter(f,d)+'</section>';}
function mwFinanceFundQuarter(f,d){if(!d?.flows)return '';const by={};d.flows.receipts.filter(r=>r.fund===f.fund.code).forEach(r=>{const key=r.date.slice(0,4)+' Q'+(Math.floor((Number(r.date.slice(5,7))-1)/3)+1),b=by[key]||(by[key]={cash:0,late:0,paid:0});if(/^funeral contribution$/i.test(r.type))b.cash+=Math.round(r.amount*100);if(/^late fee$/i.test(r.type))b.late+=Math.round(r.amount*100);});d.flows.outgoing.filter(r=>r.fund===f.fund.code&&r.type==='FAMILY').forEach(r=>{const key=r.date.slice(0,4)+' Q'+(Math.floor((Number(r.date.slice(5,7))-1)/3)+1),b=by[key]||(by[key]={cash:0,late:0,paid:0});b.paid+=Math.round(r.amount*100);});return '<h4>Fund cash activity by quarter · selected dates</h4>'+prTable(['Quarter','Contribution receipts','Separate late-fee receipts','Recorded family transfers'],Object.keys(by).sort().map(key=>[fpEscape(key),fpMoney(by[key].cash/100),fpMoney(by[key].late/100),fpMoney(by[key].paid/100)]));}
function mwFinanceOutgoingRows(flow){return flow.outgoing.filter(r=>mwFinanceOutgoingType==='ALL'||r.type===mwFinanceOutgoingType);}
function mwFinanceOutgoing(flow){return '<h3>Payouts, refunds and operating expenses</h3>'+prTable(['Category','Transactions','Amount'],flow.categories.map(r=>[fpEscape(({ADVANCE:'Family advances',FINAL:'Balances / final payments',FAMILY:'Other recorded family transfers',REFUND:'Refunds',EXPENSE:'Operating expenses',OTHER:'Unclassified / other outgoing'})[r.category]),String(r.count),fpMoney(r.amount)]).concat([['TOTAL',String(flow.outgoing.length),fpMoney(flow.outgoingTotal)]]))+'<h4>Quarterly totals · selected period only</h4>'+prTable(['Quarter','Family transfers','Refunds','Expenses','Other / unclassified','Total'],flow.quarters.map(q=>[fpEscape(q.period),fpMoney(q.family),fpMoney(q.refund),fpMoney(q.expense),fpMoney(q.other),fpMoney(q.total)]))+'<h4>Outgoing entries</h4>'+prTable(['Date','Fund','Receiver','Category','Description','Amount','Review'],mwFinanceOutgoingRows(flow).map(r=>[fpEscape(r.date),fpEscape(r.fund),fpEscape(r.receiver),fpEscape(r.stage),fpEscape(r.description),fpMoney(r.amount),fpEscape(r.classification)+'<br>PAYOUTS row '+r.row]))+'<h4>Bank adjustments · separate from recorded outgoing total</h4><p>'+fpEscape(flow.adjustments.message)+'</p>'+prTable(['Date','Fund','PAYOUTS row','Explanation','Adjustment'],flow.adjustments.rows.map(r=>[fpEscape(r.date),fpEscape(r.fund),String(r.payoutRow),fpEscape(r.explanation),fpMoney(r.amount)]));}
function mwFinanceBalanceRows(d){const q=mwFinanceSearch.trim().toLowerCase();return d.members.filter(m=>(!q||(m.memberId+' '+m.name).toLowerCase().includes(q))&&(mwFinanceOnly==='ALL'?true:mwFinanceOnly==='OVERDUE'?m.overdueFunds>=4:mwFinanceOnly==='REVIEW'?m.issues.length>0:m.total>0)).sort((a,b)=>mwFinanceSort==='NAME'?a.name.localeCompare(b.name):mwFinanceSort==='OVERDUE'?b.overdueFunds-a.overdueFunds||b.total-a.total:b.total-a.total||a.name.localeCompare(b.name));}
function mwFinanceBalances(d,board=false){const rows=board?d.members.filter(m=>m.total>0||m.issues.length).sort((a,b)=>b.total-a.total):mwFinanceBalanceRows(d),mobile=rows.map(m=>'<details><summary>'+fpEscape(m.name)+' · '+fpMoney(m.total)+'<br><small>'+fpEscape(m.memberId)+' · '+m.overdueFunds+' overdue funds</small></summary>'+prProfileButton(m.memberId,'Open member record')+m.cells.filter(c=>c.balance>0||c.balance===null).map(c=>'<p>'+fpEscape(c.code)+' · '+(c.balance===null?'Review':fpMoney(c.balance))+' · '+(c.overdue?'overdue':c.state==='REVIEW'?'verify record':'within window')+'</p>').join('')+(m.overdueFunds>=4?mwFinanceButton('Review warning','mwFinanceWarning',m.memberId):'')+'</details>').join('');return '<h3>Member balances · current records</h3><p>'+fpEscape(d.note)+'</p><p>'+rows.length+' matching members · '+fpMoney(rows.reduce((a,m)=>a+Math.round(m.total*100),0)/100)+' verified balances</p><div class="mw-balance-mobile">'+mobile+'</div><div class="mw-balance-desktop">'+prTable(['Member',...d.funds.map(f=>f.code),'Overdue funds','Total owing','Action'],rows.map(m=>[prProfileButton(m.memberId,m.name),...m.cells.map(c=>c.balance===null?'Review':c.state==='EXEMPT'?'Exempt':c.balance>0?fpMoney(c.balance)+(c.overdue?' · overdue':' · within window')+(c.lateFeePending?' · fee pending assessment':''):'—'),String(m.overdueFunds),fpMoney(m.total),m.overdueFunds>=4?mwFinanceButton('Review warning','mwFinanceWarning',m.memberId):m.issues.length?fpEscape(m.issues.join('; ')):'']).concat([['TOTAL',...d.funds.map(f=>fpMoney(rows.reduce((a,m)=>a+Math.round(Number(m.cells.find(c=>c.code===f.code)?.balance||0)*100),0)/100)),String(rows.reduce((a,m)=>a+m.overdueFunds,0)),fpMoney(rows.reduce((a,m)=>a+Math.round(m.total*100),0)/100),'']]))+'</div>';}
function mwFinanceWarning(id){mwSelectWorkspace('notices');document.getElementById('mw-notice-kind').value='FUNDS';mwNoticeLoad();showToast('Review '+id+' in the warning list. No email has been sent.');}
function mwFinanceRender(){const d=mwFinanceData;if(!d)return;const el=document.getElementById('mw-finance-content'),controls=document.getElementById('mw-finance-controls');controls.innerHTML='';if(mwFinanceView==='BALANCES'){controls.innerHTML='<div class="fp-fields"><label>Search member<input id="mw-finance-query" placeholder="Member ID or name" oninput="mwFinanceSearch=this.value;mwFinanceRenderContent()"></label><label>Show<select onchange="mwFinanceOnly=this.value;mwFinanceRenderContent()"><option value="OWING">Any owing balance</option><option value="OVERDUE">4+ overdue funds</option><option value="REVIEW">Needs verification</option><option value="ALL">All current members</option></select></label><label>Sort<select onchange="mwFinanceSort=this.value;mwFinanceRenderContent()"><option value="TOTAL">Highest balance</option><option value="OVERDUE">Most overdue funds</option><option value="NAME">Member name</option></select></label></div>';controls.querySelector('input').value=mwFinanceSearch;const sels=controls.querySelectorAll('select');sels[0].value=mwFinanceOnly;sels[1].value=mwFinanceSort;}else if(mwFinanceView==='OUTGOING'){controls.innerHTML='<label>Entry category<select onchange="mwFinanceOutgoingType=this.value;mwFinanceRenderContent()"><option value="ALL">All outgoing</option><option value="FAMILY">Family transfers</option><option value="REFUND">Refunds</option><option value="EXPENSE">Expenses</option><option value="OTHER">Other / unclassified</option></select></label>';controls.querySelector('select').value=mwFinanceOutgoingType;}mwFinanceRenderContent();}
function mwFinanceRenderContent(){const d=mwFinanceData,el=document.getElementById('mw-finance-content');if(!d)return;if(mwFinanceView==='PERFORMANCE')el.innerHTML=mwFinancePerformance(d);else if(mwFinanceView==='FUND')el.innerHTML=mwFinanceFund(d.fund,d);else if(mwFinanceView==='OUTGOING')el.innerHTML=mwFinanceOutgoing(d);else if(mwFinanceView==='BALANCES')el.innerHTML=mwFinanceBalances(d);else el.innerHTML='<h2>Board financial report</h2><p>Cash activity '+fpEscape(d.period.start)+' through '+fpEscape(d.period.end)+' · current balances generated '+fpEscape(d.generatedAt)+'</p>'+mwFinancePerformance(d)+mwFinanceOutgoing(d.flows)+mwFinanceRows(d).map(f=>mwFinanceFund(f,d)).join('')+(d.balances?mwFinanceBalances(d.balances,true):'')+'<h3>Review notes for the selected cash period</h3><ul>'+d.flows.review.map(r=>'<li>'+fpEscape(r)+'</li>').join('')+'</ul>';}
function mwFinanceExport(){const d=mwFinanceData;if(!d){showToast('Load a report first.');return;}let rows=[];if(mwFinanceView==='BALANCES'){const list=mwFinanceBalanceRows(d);rows=[['Member ID','Name',...d.funds.map(f=>f.code),'Overdue fund count','Verified balance','Issues'],...list.map(m=>[m.memberId,m.name,...m.cells.map(c=>c.balance===null?'REVIEW':c.balance),m.overdueFunds,m.total,m.issues.join('; ')])];}else if(mwFinanceView==='OUTGOING')rows=[['Date','PAYOUTS row','Fund','Receiver','Type','Description','Amount','Classification'],...mwFinanceOutgoingRows(d).map(r=>[r.date,r.row,r.fund,r.receiver,r.stage,r.description,r.amount,r.classification])];else if(mwFinanceView==='FUND')rows=[['Fund','Calculation','Amount'],...mwFinanceCalculationRows(d.fund).map(r=>[d.fund.fund.code,...r]),[],['Entry count','Payment amount','Total'],...d.fund.distribution.map(r=>[r.count,r.amount,r.total])];else rows=[['Fund','Collected contribution cash','Eligible base','Admin retained','Family share','Recorded family transfers','Bank delta','Remaining for review','Current member balances'],...mwFinanceRows(d).map(f=>[f.fund.code,f.cash,f.coreBase,f.adminFee,f.familyShare,f.recordedFamilyPaid,f.bankAdjustment,f.remaining,f.unpaid])];if(mwFinanceView==='BOARD'){rows.push([],['Outgoing entries'],['Date','PAYOUTS row','Fund','Receiver','Type','Description','Amount']);d.flows.outgoing.forEach(r=>rows.push([r.date,r.row,r.fund,r.receiver,r.stage,r.description,r.amount]));rows.push([],['Current member balances'],['Member ID','Name',...d.balances.funds.map(f=>f.code),'Overdue funds','Verified total','Issues']);d.balances.members.filter(m=>m.total>0||m.issues.length).forEach(m=>rows.push([m.memberId,m.name,...m.cells.map(c=>c.balance===null?'REVIEW':c.balance),m.overdueFunds,m.total,m.issues.join('; ')]));mwFinanceRows(d).forEach(f=>{rows.push([],['Calculation explained',f.fund.code],['Step','Amount'],...mwFinanceCalculationRows(f));});rows.push([],['Cash-period review notes'],...d.flows.review.map(x=>[x]));};mwCSV('financial-'+mwFinanceView.toLowerCase()+'.csv',[['Generated at',d.generatedAt],['Balance scope','Current records'],['Cash period',d.period?d.period.start+' through '+d.period.end:'Not applicable'],...rows]);}
function mwFinancePrint(){if(!mwFinanceData){showToast('Load a report first.');return;}const w=window.open('','_blank');if(!w){showToast('Allow the print window to open.');return;}const content=document.getElementById('mw-finance-content').innerHTML;w.document.write('<!doctype html><html><head><title>Mgwirizano financial report</title><style>body{font:11pt Arial,sans-serif;color:#09243b;margin:24px}h2,h3,h4{color:#09243b}table{border-collapse:collapse;width:100%;font-size:9pt;margin:12px 0}th,td{border-bottom:1px solid #d6e1e9;padding:7px;text-align:left;vertical-align:top}th{background:#eaf3ef}tr{break-inside:avoid}button{font:inherit;color:inherit;border:0;background:none;text-align:left}details{margin:14px 0}details>*{display:block!important}.fp-fields{display:block}.mw-report-ring,.mw-balance-mobile{display:none}.mw-balance-desktop{display:block}.mw-report-fund{break-before:page}.fp-table-wrap{overflow:visible}p{line-height:1.5}@media print{.mw-print-button{display:none}@page{size:landscape;margin:12mm}}</style></head><body><button class="mw-print-button" onclick="window.print()">Print / save PDF</button><h1>Mgwirizano Watsopano</h1><p>'+fpEscape(document.getElementById('mw-finance-status').textContent)+'</p>'+content+'</body></html>');w.document.close();w.focus();}
